{"item":{"aggregated_output":"{\"exit_code\":0,\"stderr\":\"\",\"stdout\":\"Total output lines: 310\\n\\nTotal output lines: 1779\\n\\n// SPDX-FileCopyrightText: 2024 Christina Sørensen\\r\\n// SPDX-License-Identifier: EUPL-1.2\\r\\n//\\r\\n// SPDX-FileCopyrightText: 2023-2024 Christina Sørensen, eza contributors\\r\\n// SPDX-FileCopyrightText: 2014 Benjamin Sago\\r\\n// SPDX-License-Identifier: MIT\\r\\nuse std::io::{self, Write};\\r\\n\\r\\nuse nu_ansi_term::AnsiStrings as ANSIStrings;\\r\\n\\r\\nuse crate::fs::filter::FileFilter;\\r\\nuse crate::fs::File;\\r\\nuse crate::output::cell::TextCellContents;\\r\\nuse crate::output::file_name::Options as FileStyle;\\r\\nuse crate::theme::Theme;\\r\\n\\r\\n/// The lines view literally just displays each file, line-by-line.\\r\\npub struct Render<'a> {\\r\\n    pub files: Vec<File<'a>>,\\r\\n    pub theme: &'a Theme,\\r\\n    pub file_style: &'a FileStyle,\\r\\n    pub filter: &'a FileFilter,\\r\\n}\\r\\n\\r\\nimpl<'a> Render<'a> {\\r\\n    pub fn render<W: Write>(mut self, w: &mut W) -> io::Result<()> {\\r\\n        self.filter.sort_files(&mut self.files);\\r\\n        for file in &self.files {\\r\\n            let name_cell = self.render_file(file);\\r\\n            writeln!(w, \\\"{}\\\", ANSIStrings(&name_cell))?;\\r\\n        }\\r\\n\\r\\n        Ok(())\\r\\n    }\\r\\n\\r\\n    fn render_file<'f>(&self, file: &'f File<'a>) -> TextCellContents {\\r\\n        self.file_style\\r\\n            .for_file(file, self.theme)\\r\\n            .with_link_paths()\\r\\n            .with_mount_details(false)\\r\\n            .paint()\\r\\n    }\\r\\n}\\r\\n\\r\\n\\r\\n// SPDX-FileCopyrightText: 2024 Christina Sørensen\\r\\n// SPDX-License-Identifier: EUPL-1.2\\r\\n//\\r\\n// SPDX-FileCopyrightText: 2023-2024 Christina Sørensen, eza contributors\\r\\n// SPDX-FileCopyrightText: 2014 Benjamin Sago\\r\\n// SPDX-License-Identifier: MIT\\r\\nuse std::fmt::Debug;\\r\\nuse std::path::Path;\\r\\n\\r\\nuse nu_ansi_term::{AnsiString as ANSIString, Style};\\r\\nuse path_clean;\\r\\nuse unicode_width::UnicodeWidthStr;\\r\\n\\r\\nuse crate::fs::{File, FileTarget};\\r\\nuse crate::output::cell::TextCellContents;\\r\\nuse crate::output::escape;\\r\\nuse crate::output::icons::{icon_for_file, iconify_style};\\r\\nuse crate::output::render::FiletypeColours;\\r\\nuse crate::theme::FileNameStyle;\\r\\n\\r\\n/// Basically a file name factory.\\r\\n#[derive(Debug, Copy, Clone)]\\r\\npub struct Options {\\r\\n    /// Whether to append file class characters to file names.\\r\\n    pub classify: Classify,\\r\\n\\r\\n    /// Whether to prepend icon characters before file names.\\r\\n    pub show_icons: ShowIcons,\\r\\n\\r\\n    /// How to display file names with spaces (with or without quotes).\\r\\n    pub quote_style: QuoteStyle,\\r\\n\\r\\n    /// Whether to make file names hyperlinks.\\r\\n    pub embed_hyperlinks: EmbedHyperlinks,\\r\\n\\r\\n    /// Whether to display files with their absolute path.\\r\\n    pub absolute: Absolute,\\r\\n\\r\\n    /// Whether we are in a console or redirecting the output\\r\\n    pub is_a_tty: bool,\\r\\n}\\r\\n\\r\\nimpl Options {\\r\\n    /// Create a new `FileName` that prints the given file’s name, painting it\\r\\n    /// with the remaining arguments.\\r\\n    pub fn for_file<'a, 'dir, C>(\\r\\n        self,\\r\\n        file: &'a File<'dir>,\\r\\n        colours: &'a C,\\r\\n    ) -> FileName<'a, 'dir, C> {\\r\\n        FileName {\\r\\n            file,\\r\\n            colours,\\r\\n            link_style: LinkStyle::JustFilenames,\\r\\n            options: self,\\r\\n            target: if file.is_link() {\\r\\n                Some(file.link_target())\\r\\n            } else {\\r\\n                None\\r\\n            },\\r\\n            mount_style: MountStyle::JustDirectoryNames,\\r\\n        }\\r\\n    }\\r\\n}\\r\\n\\r\\n/// When displaying a file name, there needs to be some way to handle broken\\r\\n/// links, depending on how long the resulting Cell can be.\\r\\n#[derive(PartialEq, Debug, Copy, Clone)]\\r\\nenum LinkStyle {\\r\\n    /// Just display the file names, but colour them differently if they’re\\r\\n    /// a broken link or can’t be followed.\\r\\n    JustFilenames,\\r\\n\\r\\n    /// Display all files in their usual style, but follow each link with an\\r\\n    /// arrow pointing to their path, colouring the path differently if it’s\\r\\n    /// a broken link, and doing nothing if it can’t be followed.\\r\\n    FullLinkPaths,\\r\\n}\\r\\n\\r\\n/// Whether to append file class characters to the file names.\\r\\n#[derive(PartialEq, Eq, Debug, Default, Copy, Clone)]\\r\\npub enum Classify {\\r\\n    /// Just display the file names, without any characters.\\r\\n    #[default]\\r\\n    JustFilenames,\\r\\n\\r\\n    /// Always add a character after the file name depending on what class of\\r\\n    /// file it is.\\r\\n    AddFileIndicators,\\r\\n\\r\\n    // Like previous, but only when output is going to a terminal, not otherwise.\\r\\n    AutomaticAddFileIndicators,\\r\\n}\\r\\n\\r\\n/// When displaying a directory name, there needs to be some way to handle\\r\\n/// mount details, depending on how long the resulting Cell can be.\\r\\n#[derive(PartialEq, Debug, Copy, Clone)]\\r\\nenum MountStyle {\\r\\n    /// Just display the directory names.\\r\\n    JustDirectoryNames,\\r\\n\\r\\n    /// Display mount points as directories and include information about\\r\\n    /// the filesystem that's mounted there.\\r\\n    MountInfo,\\r\\n}\\r\\n\\r\\n/// Whether and how to show icons.\\r\\n#[derive(PartialEq, Debug, Copy, Clone)]\\r\\npub enum ShowIcons {\\r\\n    /// Display icons next to file names, with the given number of spaces between\\r\\n    /// the icon and th...58 characters truncated... file: &File<'_>, xattrs: bool) -> Option<f::PermissionsPlus> {\\r\\n        Some(f::PermissionsPlus {\\r\\n            file_type: file.type_char(),\\r\\n            #[cfg(windows)]\\r\\n            attributes: file.attributes()?,\\r\\n            xattrs,\\r\\n        })\\r\\n    }\\r\\n\\r\\n    #[cfg(unix)]\\r\\n    fn octal_permissions(&self, file: &File<'_>) -> Option<f::OctalPermissions> {\\r\\n        file.permissions()\\r\\n            .map(|p| f::OctalPermissions { permissions: p })\\r\\n    }\\r\\n\\r\\n    fn display(\\r\\n        &self,\\r\\n        file: &File<'_>,\\r\\n        column: Column,\\r\\n        xattrs: bool,\\r\\n        color_scale_info: Option<ColorScaleInformation>,\\r\\n    ) -> TextCell {\\r\\n        match column {\\r\\n            Column::Permissions => self.permissions_plus(file, xattrs).render(self.theme),\\r\\n            Column::FileSize => file.size().render(\\r\\n                self.theme,\\r\\n                self.size_format,\\r\\n                &self.env.numeric,\\r\\n                color_scale_info,\\r\\n            ),\\r\\n            #[cfg(unix)]\\r\\n            Column::HardLinks => file.links().render(self.theme, &self.env.numeric),\\r\\n            #[cfg(unix)]\\r\\n            Column::Inode => file.inode().render(self.theme.ui.inode.unwrap_or_default()),\\r\\n            #[cfg(unix)]\\r\\n            Column::Blocksize => {\\r\\n                file.blocksize()\\r\\n                    .render(self.theme, self.size_format, &self.env.numeric)\\r\\n            }\\r\\n            #[cfg(unix)]\\r\\n            Column::User => {\\r\\n                file.user()\\r\\n                    .render(self.theme, &*self.env.lock_users(), self.user_format)\\r\\n            }\\r\\n            #[cfg(unix)]\\r\\n            Column::Group => file.group().render(\\r\\n                self.theme,\\r\\n                &*self.env.lock_users(),\\r\\n                self.user_format,\\r\\n                self.group_format,\\r\\n                file.user(),\\r\\n            ),\\r\\n            #[cfg(unix)]\\r\\n            Column::SecurityContext => file.security_context().render(self.theme),\\r\\n            Column::FileFlags => file\\r\\n                .flags()\\r\\n                .render(self.theme.ui.flags.unwrap_or_default(), self.flags_format),\\r\\n            Column::GitStatus => self.git_status(file).render(self.theme),\\r\\n            Column::SubdirGitRepo(status) => self.subdir_git_repo(file, status).render(self.theme),\\r\\n            #[cfg(unix)]\\r\\n            Column::Octal => self\\r\\n                .octal_permissions(file)\\r\\n                .render(self.theme.ui.octal.unwrap_or_default()),\\r\\n\\r\\n            Column::Timestamp(time_type) => time_type.get_corresponding_time(file).render(\\r\\n                if color_scale_info.is_some_and(|csi| csi.options.mode == ColorScaleMode::Gradient)\\r\\n                {\\r\\n                    color_scale_info.unwrap().apply_time_gradient(\\r\\n                        self.theme.ui.date.unwrap_or_default(),\\r\\n                        file,\\r\\n                        time_type,\\r\\n                    )\\r\\n                } else {\\r\\n                    self.theme.ui.date.unwrap_or_default()\\r\\n                },\\r\\n                self.env.time_offset,\\r\\n                self.time_format.clone(),\\r\\n            ),\\r\\n        }\\r\\n    }\\r\\n\\r\\n    fn git_status(&self, file: &File<'_>) -> f::Git {\\r\\n        debug!(\\\"Getting Git status for file {:?}\\\", file.path);\\r\\n\\r\\n        self.git\\r\\n            .map(|g| g.get(&file.path, file.is_directory()))\\r\\n            .unwrap_or_default()\\r\\n    }\\r\\n\\r\\n    fn subdir_git_repo(&self, file: &File<'_>, status: bool) -> f::SubdirGitRepo {\\r\\n        debug!(\\\"Getting subdir repo status for path {:?}\\\", file.path);\\r\\n\\r\\n        if file.is_directory() {\\r\\n            return f::SubdirGitRepo::from_path(&file.path, status);\\r\\n        }\\r\\n        f::SubdirGitRepo::default()\\r\\n    }\\r\\n\\r\\n    #[must_use]\\r\\n    pub fn render(&self, row: Row) -> TextCell {\\r\\n        let mut cell = TextCell::default();\\r\\n\\r\\n        let iter = row.cells.into_iter().zip(self.widths.iter()).enumerate();\\r\\n\\r\\n        for (n, (this_cell, width)) in iter {\\r\\n            let padding = width - *this_cell.width;\\r\\n\\r\\n            match self.columns[n].alignment() {\\r\\n                Alignment::Left => {\\r\\n                    cell.append(this_cell);\\r\\n                    cell.add_spaces(padding);\\r\\n                }\\r\\n                Alignment::Right => {\\r\\n                    cell.add_spaces(padding);\\r\\n                    cell.append(this_cell);\\r\\n                }\\r\\n            }\\r\\n\\r\\n            cell.add_spaces(1);\\r\\n        }\\r\\n\\r\\n        cell\\r\\n    }\\r\\n}\\r\\n\\r\\npub struct TableWidths(Vec<usize>);\\r\\n\\r\\nimpl Deref for TableWidths {\\r\\n    type Target = [usize];\\r\\n\\r\\n    fn deref(&self) -> &Self::Target {\\r\\n        &self.0\\r\\n    }\\r\\n}\\r\\n\\r\\nimpl TableWidths {\\r\\n    #[must_use]\\r\\n    pub fn zero(count: usize) -> Self {\\r\\n        Self(vec![0; count])\\r\\n    }\\r\\n\\r\\n    pub fn add_widths(&mut self, row: &Row) {\\r\\n        for (old_width, cell) in self.0.iter_mut().zip(row.cells.iter()) {\\r\\n            *old_width = max(*old_width, *cell.width);\\r\\n        }\\r\\n    }\\r\\n\\r\\n    #[must_use]\\r\\n    pub fn total(&self) -> usize {\\r\\n        self.0.len() + self.0.iter().sum::<usize>()\\r\\n    }\\r\\n}\\r\\n\\r\\n\"}","command":"shell_command","command_index":2,"command_line":"{\"command\":\"Get-Content -Raw rust-reference/src/output/lines.rs; Get-Content -Raw rust-reference/src/output/file_name.rs; Get-Content -Raw rust-reference/src/output/details.rs; Get-Content -Raw rust-reference/src/output/table.rs\",\"workdir\":\"C:\\\\Users\\\\liuliu\\\\Documents\\\\tura-benchmark\\\\raw\\\\project-rebuild-source-port\\\\r-c7e67bc81e\\\\eza\\\\tura-balanced-1\\\\workspace\"}","command_type":"shell_command","id":"runtime-18c0fdb3810a59a4.tool.command_run:call_BCFmtrR5toNA39ni17NPPJ7Q:2","provider_tool_call_id":"call_BCFmtrR