{"item":{"aggregated_output":"{\"exit_code\":0,\"stderr\":\"\",\"stdout\":\"Total output lines: 296\\n\\nTotal output lines: 715\\n\\n// SPDX-FileCopyrightText: 2024 Christina Sørensen\\r\\n// SPDX-License-Identifier: EUPL-1.2\\r\\n//\\r\\n// SPDX-FileCopyrightText: 2023-2024 Christina Sørensen, eza contributors\\r\\n// SPDX-FileCopyrightText: 2014 Benjamin Sago\\r\\n// SPDX-License-Identifier: MIT\\r\\n//! Tree structures, such as `├──` or `└──`, used in a tree view.\\r\\n//!\\r\\n//! ## Constructing Tree Views\\r\\n//!\\r\\n//! When using the `--tree` argument, instead of a vector of cells, each row\\r\\n//! has a `depth` field that indicates how far deep in the tree it is: the top\\r\\n//! level has depth 0, its children have depth 1, and *their* children have\\r\\n//! depth 2, and so on.\\r\\n//!\\r\\n//! On top of this, it also has a `last` field that specifies whether this is\\r\\n//! the last row of this particular consecutive set of rows. This doesn’t\\r\\n//! affect the file’s information; it’s just used to display a different set of\\r\\n//! Unicode tree characters! The resulting table looks like this:\\r\\n//!\\r\\n//! ```text\\r\\n//!     ┌───────┬───────┬───────────────────────┐\\r\\n//!     │ Depth │ Last  │ Output                │\\r\\n//!     ├───────┼───────┼───────────────────────┤\\r\\n//!     │     0 │       │ documents             │\\r\\n//!     │     1 │ false │ ├── this_file.txt     │\\r\\n//!     │     1 │ false │ ├── that_file.txt     │\\r\\n//!     │     1 │ false │ ├── features          │\\r\\n//!     │     2 │ false │ │   ├── feature_1.rs  │\\r\\n//!     │     2 │ false │ │   ├── feature_2.rs  │\\r\\n//!     │     2 │ true  │ │   └── feature_3.rs  │\\r\\n//!     │     1 │ true  │ └── pictures          │\\r\\n//!     │     2 │ false │     ├── garden.jpg    │\\r\\n//!     │     2 │ false │     ├── flowers.jpg   │\\r\\n//!     │     2 │ false │     ├── library.png   │\\r\\n//!     │     2 │ true  │     └── space.tiff    │\\r\\n//!     └───────┴───────┴───────────────────────┘\\r\\n//! ```\\r\\n//!\\r\\n//! Creating the table like this means that each file has to be tested to see\\r\\n//! if it’s the last one in the group. This is usually done by putting all the\\r\\n//! files in a vector beforehand, getting its length, then comparing the index\\r\\n//! of each file to see if it’s the last one. (As some files may not be\\r\\n//! successfully `stat`ted, we don’t know how many files are going to exist in\\r\\n//! each directory)\\r\\n\\r\\n#[derive(PartialEq, Eq, Debug, Copy, Clone)]\\r\\npub enum TreePart {\\r\\n    /// Rightmost column, *not* the last in the directory.\\r\\n    Edge,\\r\\n\\r\\n    /// Not the rightmost column, and the directory has not finished yet.\\r\\n    Line,\\r\\n\\r\\n    /// Rightmost column, and the last in the directory.\\r\\n    Corner,\\r\\n\\r\\n    /// Not the rightmost column, and the directory *has* finished.\\r\\n    Blank,\\r\\n}\\r\\n\\r\\nimpl TreePart {\\r\\n    /// Turn this tree part into ASCII-licious box drawing characters!\\r\\n    /// (Warning: not actually ASCII)\\r\\n    pub fn ascii_art(self) -> &'static str {\\r\\n        #[rustfmt::skip]\\r\\n        return match self {\\r\\n            Self::Edge    => \\\"├── \\\",\\r\\n            Self::Line    => \\\"│   \\\",\\r\\n            Self::Corner  => \\\"└── \\\",\\r\\n            Self::Blank   => \\\"    \\\",\\r\\n        };\\r\\n    }\\r\\n}\\r\\n\\r\\n/// A **tree trunk** builds up arrays of tree parts over multiple depths.\\r\\n#[derive(Debug, Default)]\\r\\npub struct TreeTrunk {\\r\\n    /// A stack tracks which tree characters should be printed. It’s\\r\\n    /// necessary to maintain information about the previously-printed\\r\\n    /// lines, as the output will change based on any previous entries.\\r\\n    stack: Vec<TreePart>,\\r\\n\\r\\n    /// A tuple for the last ‘depth’ and ‘last’ parameters that are passed in.\\r\\n    last_params: Option<TreeParams>,\\r\\n}\\r\\n\\r\\n#[derive(Debug, Copy, Clone)]\\r\\npub struct TreeParams {\\r\\n    /// How many directories deep into the tree structure this is. Directories\\r\\n    /// on top have depth 0.\\r\\n    depth: TreeDepth,\\r\\n\\r\\n    /// Whether this is the last entry in the directory.\\r\\n    last: bool,\\r\\n}\\r\\n\\r\\n#[derive(Debug, Copy, Clone)]\\r\\npub struct TreeDepth(pub usize);\\r\\n\\r\\nimpl TreeTrunk {\\r\\n    /// Calculates the tree parts for an entry at the given depth and\\r\\n    /// last-ness. The depth is used to determine where in the stack the tree\\r\\n    /// part should be inserted, and the last-ness is used to determine which\\r\\n    /// type of tree part to insert.\\r\\n    ///\\r\\n    /// This takes a `&mut self` because the results of each file are stored\\r\\n    /// and used in future rows.\\r\\n    pub fn new_row(&mut self, params: TreeParams) -> &[TreePart] {\\r\\n        // If this isn’t our first iteration, then update the tree parts thus\\r\\n        // far to account for there being another row after it.\\r\\n        if let Some(last) = self.last_params {\\r\\n            self.stack[last.depth.0] = if last.last {\\r\\n                TreePart::Blank\\r\\n            } else {\\r\\n                TreePart::Line\\r\\n            };\\r\\n        }\\r\\n\\r\\n        // Make sure the stack has enough space, then add or modify another\\r\\n        // part into it.\\r\\n        self.stack.resize(params.depth.0 + 1, TreePart::Edge);\\r\\n        self.stack[params.depth.0] = if params.last {\\r\\n            TreePart::Corner\\r\\n        } else {\\r\\n            TreePart::Edge\\r\\n        };\\r\\n\\r\\n        self.la...57 characters truncated...endered with fewer rows,\\r\\n        // then render a details list view instead.\\r\\n        if let RowThreshold::MinimumRows(minimum_rows) = self.row_threshold {\\r\\n            if grid.row_count() < minimum_rows {\\r\\n                let Self {\\r\\n                    dir,\\r\\n                    files,\\r\\n                    theme,\\r\\n                    file_style,\\r\\n                    details: opts,\\r\\n                    filter,\\r\\n                    git_ignoring,\\r\\n                    git,\\r\\n                    git_repos,\\r\\n                    ..\\r\\n                } = self;\\r\\n\\r\\n                let r = DetailsRender {\\r\\n                    dir,\\r\\n                    files,\\r\\n                    theme,\\r\\n                    file_style,\\r\\n                    opts,\\r\\n                    recurse: None,\\r\\n                    filter,\\r\\n                    git_ignoring,\\r\\n                    git,\\r\\n                    git_repos,\\r\\n                };\\r\\n                return r.render(w);\\r\\n            }\\r\\n        }\\r\\n\\r\\n        if self.details.header {\\r\\n            let row = table.header_row();\\r\\n            let name = TextCell::paint_str(self.theme.ui.header.unwrap_or_default(), \\\"Name\\\")\\r\\n                .strings()\\r\\n                .to_string();\\r\\n            let s = table.render(row).strings().to_string();\\r\\n            let combined_header = format!(\\\"{s} {name}\\\");\\r\\n            let header_width = ansi_width::ansi_width(&combined_header);\\r\\n            for column_width in grid.column_widths() {\\r\\n                let padding = \\\" \\\".repeat((column_width + 4).saturating_sub(header_width));\\r\\n                write!(w, \\\"{combined_header}{padding}\\\")?;\\r\\n            }\\r\\n            writeln!(w)?;\\r\\n        }\\r\\n\\r\\n        write!(w, \\\"{grid}\\\")?;\\r\\n\\r\\n        Ok(())\\r\\n    }\\r\\n\\r\\n    fn make_table(&mut self, options: &'a TableOptions) -> Table<'a> {\\r\\n        match (self.git, self.dir) {\\r\\n            (Some(g), Some(d)) => {\\r\\n                if !g.has_anything_for(&d.path) {\\r\\n                    self.git = None;\\r\\n                }\\r\\n            }\\r\\n            (Some(g), None) => {\\r\\n                if !self.files.iter().any(|f| g.has_anything_for(&f.path)) {\\r\\n                    self.git = None;\\r\\n                }\\r\\n            }\\r\\n            (None, _) => { /* Keep Git how it is */ }\\r\\n        }\\r\\n\\r\\n        let mut table = Table::new(options, self.git, self.theme, self.git_repos);\\r\\n\\r\\n        // The header row will be printed separately, but it should be\\r\\n        // considered for the width calculations.\\r\\n        if self.details.header {\\r\\n            let row = table.header_row();\\r\\n            table.add_widths(&row);\\r\\n        }\\r\\n\\r\\n        table\\r\\n    }\\r\\n}\\r\\n\\r\\n\\r\\n// SPDX-FileCopyrightText: 2024 Christina Sørensen\\r\\n// SPDX-License-Identifier: EUPL-1.2\\r\\n//\\r\\n// SPDX-FileCopyrightText: 2023-2024 Christina Sørensen, eza contributors\\r\\n// SPDX-FileCopyrightText: 2014 Benjamin Sago\\r\\n// SPDX-License-Identifier: MIT\\r\\n#[cfg(target_os = \\\"windows\\\")]\\r\\npub use self::cell::TextCell;\\r\\npub use self::escape::escape;\\r\\n\\r\\npub mod color_scale;\\r\\npub mod details;\\r\\npub mod file_name;\\r\\npub mod grid;\\r\\npub mod grid_details;\\r\\npub mod icons;\\r\\npub mod lines;\\r\\npub mod render;\\r\\npub mod table;\\r\\npub mod time;\\r\\n\\r\\nmod cell;\\r\\nmod escape;\\r\\nmod tree;\\r\\n\\r\\n/// The **view** contains all information about how to format output.\\r\\n#[derive(Debug)]\\r\\npub struct View {\\r\\n    pub mode: Mode,\\r\\n    pub width: TerminalWidth,\\r\\n    pub file_style: file_name::Options,\\r\\n    pub deref_links: bool,\\r\\n    pub follow_links: bool,\\r\\n    pub total_size: bool,\\r\\n}\\r\\n\\r\\n/// The **mode** is the “type” of output.\\r\\n#[derive(PartialEq, Eq, Debug)]\\r\\n#[allow(clippy::large_enum_variant)]\\r\\npub enum Mode {\\r\\n    Grid(grid::Options),\\r\\n    Details(details::Options),\\r\\n    GridDetails(grid_details::Options),\\r\\n    Lines,\\r\\n}\\r\\n\\r\\n/// The width of the terminal requested by the user.\\r\\n#[derive(PartialEq, Eq, Debug, Copy, Clone)]\\r\\npub enum TerminalWidth {\\r\\n    /// The user requested this specific number of columns.\\r\\n    Set(usize),\\r\\n\\r\\n    /// Look up the terminal size at runtime.\\r\\n    Automatic,\\r\\n}\\r\\n\\r\\nimpl TerminalWidth {\\r\\n    #[must_use]\\r\\n    pub fn actual_terminal_width(self) -> Option<usize> {\\r\\n        // All of stdin, stdout, and stderr could not be connected to a\\r\\n        // terminal, but we’re only interested in stdout because it’s\\r\\n        // where the output goes.\\r\\n\\r\\n        #[cfg(unix)]\\r\\n        let stdout_term_width =\\r\\n            { terminal_size::terminal_size_of(std::io::stdout()).map(|(w, _h)| w.0 as _) };\\r\\n        #[cfg(windows)]\\r\\n        let stdout_term_width = {\\r\\n            use std::os::windows::io::BorrowedHandle;\\r\\n            use windows_sys::Win32::System::Console::{GetStdHandle, STD_OUTPUT_HANDLE};\\r\\n            terminal_size::terminal_size_of(unsafe {\\r\\n                BorrowedHandle::borrow_raw(GetStdHandle(STD_OUTPUT_HANDLE))\\r\\n            })\\r\\n            .map(|(w, _h)| w.0 as _)\\r\\n        };\\r\\n\\r\\n        #[rustfmt::skip]\\r\\n        return match self {\\r\\n            Self::Set(width)  => Some(width),\\r\\n            Self::Automatic   => stdout_term_width,\\r\\n        };\\r\\n    }\\r\\n}\\r\\n\\r\\n\"}","command":"shell_command","command_index":3,"command_line":"{\"command\":\"Get-Content -Raw rust-reference/src/output/tree.rs; Get-Content -Raw rust-reference/src/output/grid.rs; Get-Content -Raw rust-reference/src/output/grid_details.rs; Get-Content -Raw rust-reference/src/output/mod.rs\",\"workdir\":\"C:\\\\Users\\\\liuliu\\\\Documents\\\\tura-benchmark\\\\raw\\\\project-rebuild-source-port\\\\r-c7e67bc81e\\\\eza\\\\tura-balanced-1\\\\workspace\"}","command_type":"shell_command","id":"runtime-18c0fdb3810a59a4.tool.command_run:call_BCFmtrR5toNA39ni17NPPJ7Q:3","provider_tool_call_id":"call_BCFmtrR5toNA39ni17NPPJ7Q