{"item":{"aggregated_output":"{\"exit_code\":0,\"stderr\":\"\",\"stdout\":\"/// The file’s Unix permission bitfield, with one entry per bit.\\r\\n#[derive(Copy, Clone)]\\r\\n#[rustfmt::skip]\\r\\npub struct Permissions {\\r\\n    pub user_read:      bool,\\r\\n    pub user_write:     bool,\\r\\n    pub user_execute:   bool,\\r\\n\\r\\n    pub group_read:     bool,\\r\\n    pub group_write:    bool,\\r\\n    pub group_execute:  bool,\\r\\n\\r\\n    pub other_read:     bool,\\r\\n    pub other_write:    bool,\\r\\n    pub other_execute:  bool,\\r\\n\\r\\n    pub sticky:         bool,\\r\\n    pub setgid:         bool,\\r\\n    pub setuid:         bool,\\r\\n}\\r\\n\\r\\n/// The file's `FileAttributes` field, available only on Windows.\\r\\n#[derive(Copy, Clone)]\\r\\n#[rustfmt::skip]\\r\\n#[cfg(windows)]\\r\\npub struct Attributes {\\r\\n    pub archive:         bool,\\r\\n    pub directory:       bool,\\r\\n    pub readonly:        bool,\\r\\n    pub hidden:          bool,\\r\\n    pub system:          bool,\\r\\n    pub reparse_point:   bool,\\r\\n}\\r\\n\\r\\n/// The three pieces of information that are displayed as a single column in\\r\\n/// the details view. These values are fused together to make the output a\\r\\n/// little more compressed.\\r\\n#[derive(Copy, Clone)]\\r\\npub struct PermissionsPlus {\\r\\n    #[allow(unused)]\\r\\n    pub file_type: Type,\\r\\n    #[cfg(unix)]\\r\\n    pub permissions: Permissions,\\r\\n    #[cfg(windows)]\\r\\n    pub attributes: Attributes,\\r\\n    #[allow(unused)]\\r\\n    pub xattrs: bool,\\r\\n}\\r\\n\\r\\n/// The permissions encoded as octal values\\r\\n#[derive(Copy, Clone)]\\r\\npub struct OctalPermissions {\\r\\n    pub permissions: Permissions,\\r\\n}\\r\\n\\r\\n/// A file’s number of hard links on the filesystem.\\r\\n///\\r\\n/// Under Unix, a file can exist on the filesystem only once but appear in\\r\\n/// multiple directories. However, it’s rare (but occasionally useful!) for a\\r\\n/// regular file to have a link count greater than 1, so we highlight the\\r\\n/// block count specifically for this case.\\r\\n#[allow(unused)]\\r\\n#[derive(Copy, Clone)]\\r\\npub struct Links {\\r\\n    /// The actual link count.\\r\\n    pub count: nlink_t,\\r\\n\\r\\n    /// Whether this file is a regular file with more than one hard link.\\r\\n    pub multiple: bool,\\r\\n}\\r\\n\\r\\n/// A file’s inode. Every directory entry on a Unix filesystem has an inode,\\r\\n/// including directories and links, so this is applicable to everything exa\\r\\n/// can deal with.\\r\\n#[allow(unused)]\\r\\n#[derive(Copy, Clone)]\\r\\npub struct Inode(pub ino_t);\\r\\n\\r\\n/// A file's size of allocated file system blocks.\\r\\n#[derive(Copy, Clone)]\\r\\n#[cfg(unix)]\\r\\npub enum Blocksize {\\r\\n    /// This file has the given number of blocks.\\r\\n    Some(u64),\\r\\n\\r\\n    /// This file isn’t of a type that can take up blocks.\\r\\n    None,\\r\\n}\\r\\n\\r\\n/// The ID of the user that owns a file. This will only ever be a number;\\r\\n/// looking up the username is done in the `display` module.\\r\\n#[allow(unused)]\\r\\n#[derive(Copy, Clone)]\\r\\npub struct User(pub uid_t);\\r\\n\\r\\n/// The ID of the group that a file belongs to.\\r\\n#[allow(unused)]\\r\\n#[derive(Copy, Clone)]\\r\\npub struct Group(pub gid_t);\\r\\n\\r\\n/// A file’s size, in bytes. This is usually formatted by the `number_prefix`\\r\\n/// crate into something human-readable.\\r\\n#[derive(Copy, Clone)]\\r\\npub enum Size {\\r\\n    /// This file has a defined size.\\r\\n    Some(u64),\\r\\n\\r\\n    /// This file has no size, or has a size but we aren’t interested in it.\\r\\n    ///\\r\\n    /// Under Unix, directory entries that aren’t regular files will still\\r\\n    /// have a file size. For example, a directory will just contain a list of\\r\\n    /// its files as its “contents” and will be specially flagged as being a\\r\\n    /// directory, rather than a file. However, seeing the “file size” of this\\r\\n    /// data is rarely useful — I can’t think of a time when I’ve seen it and\\r\\n    /// learnt something. So we discard it and just output “-” instead.\\r\\n    ///\\r\\n    /// See this answer for more: <https://unix.stackexchange.com/a/68266>\\r\\n    None,\\r\\n\\r\\n    /// This file is a block or character device, so instead of a size, print\\r\\n    /// out the file’s major and minor device IDs.\\r\\n    ///\\r\\n    /// This is what ls does as well. Without it, the devices will just have\\r\\n    /// file sizes of zero.\\r\\n    DeviceIDs(DeviceIDs),\\r\\n}\\r\\n\\r\\n/// The major and minor device IDs that gets displayed for device files.\\r\\n///\\r\\n/// You can see what these device numbers mean:\\r\\n/// - <http://www.lanana.org/docs/device-list/>\\r\\n/// - <http://www.lanana.org/docs/device-list/devices-2.6+.txt>\\r\\n#[derive(Copy, Clone)]\\r\\npub struct DeviceIDs {\\r\\n    pub major: u32,\\r\\n    pub minor: u32,\\r\\n}\\r\\n\\r\\n/// One of a file’s timestamps (created, accessed, or modified).\\r\\n#[derive(Copy, Clone, PartialEq, Eq, PartialOrd, Ord)]\\r\\npub struct Time {\\r\\n\"}","command":"shell_command","command_index":6,"command_line":"{\"command\":\"$p='rust-reference/src/fs/fields.rs'; $c=Get-Content $p; $c[70..210]; $c[430..620]\",\"workdir\":\"C:\\\\Users\\\\liuliu\\\\Documents\\\\tura-benchmark\\\\raw\\\\project-rebuild-source-port\\\\r-c7e67bc81e\\\\eza\\\\tura-balanced-1\\\\workspace\"}","command_type":"shell_command","id":"runtime-18c0fdca2eee43d0.tool.command_run:call_eZedCty4jsrMIOUJI7KSX9zs:6","provider_tool_call_id":"call_eZedCty4jsrMIOUJI7KSX9zs","status":"completed","step":1,"type":"command_execution"},"type":"item.completed"}
{"item":{"aggregated_output":"{\"exit_code\":0,\"stderr\":\"\",\"stdout\":\"// SPDX-FileCopyrightText: 2024 Christina Sørensen\\r\\n// SPDX-License-Identifier: EUPL-1.2\\r\\n//\\r\\n// SPDX-FileCopyrightText: 2023-2024 Christina Sørensen, eza contributors\\r\\n// SPDX-FileCopyrightText: 2014 Benjamin Sago\\r\\n// SPDX-License-Identifier: MIT\\r\\n//! Timestamp formatting.\\r\\n\\r\\nuse chrono::prelude::*;\\r\\nuse core::cmp::max;\\r\\nuse std::sync::LazyLock;\\r\\nuse std::time::Duration;\\r\\nuse unicode_width::UnicodeWidthStr;\\r\\n\\r\\n/// Every timestamp in exa needs to be rendered by a **time format**.\\r\\n/// Formatting times is tricky, because how a timestamp is rendered can\\r\\n/// depend on one or more of the following:\\r\\n///\\r\\n/// - The user’s locale, for printing the month name as “Feb”, or as “fév”,\\r\\n///   or as “2月”;\\r\\n/// - The current year, because certain formats will be less precise when\\r\\n///   dealing with dates far in the past;\\r\\n/// - The formatting style that the user asked for on the command-line.\\r\\n///\\r\\n/// Because not all formatting styles need the same data, they all have their\\r\\n/// own enum variants. It’s not worth looking the locale up if the formatter\\r\\n/// prints month names as numbers.\\r\\n///\\r\\n/// Also, eza supports *custom* styles, where the user enters a\\r\\n/// format string in an environment variable or something. Just these four.\\r\\n#[derive(PartialEq, Eq, Debug, Clone)]\\r\\npub enum TimeFormat {\\r\\n    /// The **default format** uses the user’s locale to print month names,\\r\\n    /// and specifies the timestamp down to the minute for recent times, and\\r\\n    /// day for older times.\\r\\n    DefaultFormat,\\r\\n\\r\\n    /// Use the **ISO format**, which specifies the timestamp down to the\\r\\n    /// minute for recent times, and day for older times. It uses a number\\r\\n    /// for the month so it doesn’t use the locale.\\r\\n    ISOFormat,\\r\\n\\r\\n    /// Use the **long ISO format**, which specifies the timestamp down to the\\r\\n    /// minute using only numbers, without needing the locale or year.\\r\\n    LongISO,\\r\\n\\r\\n    /// Use the **full ISO format**, which specifies the timestamp down to the\\r\\n    /// millisecond and includes its offset down to the minute. This too uses\\r\\n    /// only numbers so doesn’t require any special consideration.\\r\\n    FullISO,\\r\\n\\r\\n    /// Use a relative but fixed width representation.\\r\\n    Relative,\\r\\n\\r\\n    /// Use custom formats, optionally a different custom format can be\\r\\n    /// specified for recent times, otherwise the same custom format will be\\r\\n    /// used for both recent and non-recent times.\\r\\n    Custom {\\r\\n        non_recent: String,\\r\\n        recent: Option<String>,\\r\\n    },\\r\\n}\\r\\n\\r\\nimpl TimeFormat {\\r\\n    #[must_use]\\r\\n    pub fn format(self, time: &DateTime<FixedOffset>) -> String {\\r\\n        #[rustfmt::skip]\\r\\n        return match self {\\r\\n            Self::DefaultFormat                 => default(time),\\r\\n            Self::ISOFormat                     => iso(time),\\r\\n            Self::LongISO                       => long(time),\\r\\n            Self::FullISO                       => full(time),\\r\\n            Self::Relative                      => relative(time),\\r\\n            Self::Custom { non_recent, recent } => custom(\\r\\n                time, non_recent.as_str(), recent.as_deref()\\r\\n            ),\\r\\n        };\\r\\n    }\\r\\n}\\r\\n\\r\\nfn default(time: &DateTime<FixedOffset>) -> String {\\r\\n    let month = &*LOCALE.short_month_name(time.month0() as usize);\\r\\n    let month_width = short_month_padding(*MAX_MONTH_WIDTH, month);\\r\\n    let format = if time.year() == *CURRENT_YEAR {\\r\\n        format!(\\\"%_d {month:<month_width$} %H:%M\\\")\\r\\n    } else {\\r\\n        format!(\\\"%_d {month:<month_width$}  %Y\\\")\\r\\n    };\\r\\n    time.format(format.as_str()).to_string()\\r\\n}\\r\\n\\r\\n/// Convert between Unicode width and width in chars to use in format!.\\r\\n/// ex: in Japanese, 月 is one character, but it has the width of two.\\r\\n/// For alignment purposes, we take the real display width into account.\\r\\n/// So, `MAXIMUM_MONTH_WIDTH` (“12月”) = 4, but if we use `{:4}` in format!,\\r\\n/// it will add a space (“ 12月”) because format! counts characters.\\r\\n/// Conversely, a char can have a width of zero (like combining diacritics)\\r\\nfn short_month_padding(max_month_width: usize, month: &str) -> usize {\\r\\n    let shift = month.chars().count() as isize - UnicodeWidthStr::width(month) as isize;\\r\\n    (max_month_width as isize + shift) as usize\\r\\n}\\r\\n\\r\\nfn iso(time: &DateTime<FixedOffset>) -> String {\\r\\n    if time.year() == *CURRENT_YEAR {\\r\\n        time.format(\\\"%m-%d %H:%M\\\").to_string()\\r\\n    } else {\\r\\n        time.format(\\\"%Y-%m-%d\\\").to_string()\\r\\n    }\\r\\n}\\r\\n\\r\\nfn long(time: &DateTime<FixedOffset>) -> String {\\r\\n    time.format(\\\"%Y-%m-%d %H:%M\\\").to_string()\\r\\n}\\r\\n\\r\\n// #[allow(trivial_numeric_casts)]\\r\\nfn relative(time: &DateTime<FixedOffset>) -> String {\\r\\n    timeago::Formatter::new()\\r\\n        .ago(\\\"\\\")\\r\\n        .convert(Duration::from_secs(\\r\\n            max(0, Local::now().timestamp() - time.timestamp())\\r\\n                // this .unwrap is safe since the call above can never result in a\\r\\n                // value < 0\\r\\n                .try_into()\\r\\n                .unwrap(),\\r\\n        ))\\r\\n}\\r\\n\\r\\nfn full(time: &DateTime<FixedOffset>) -> String {\\r\\n    time.format(\\\"%Y-%m-%d %H:%M:%S.%f %z\\\").to_string()\\r\\n}\\r\\n\\r\\nfn custom(time: &DateTime<FixedOffset>, non_recent_fmt: &str, recent_fmt: Option<&str>) -> String {\\r\\n    if let Some(recent_fmt) = recent_fmt {\\r\\n        if time.year() == *CURRENT_YEAR {\\r\\n            time.format(recent_fmt).to_string()\\r\\n        } else {\\r\\n            time.format(non_recent_fmt).to_string()\\r\\n        }\\r\\n    } else {\\r\\n        time.format(non_recent_fmt).to_string()\\r\\n    }\\r\\n}\\r\\n\\r\\nstatic CURRENT_YEAR: LazyLock<i32> = LazyLock::new(|| Local::now().year());\\r\\n\\r\\nstatic LOCALE: LazyLock<locale::Time> =\\r\\n    LazyLock::new(|| locale::Time::load_user_locale().unwrap_or_else(|_| locale::Time::english()));\\r\\n\\r\\nstatic MAX_MONTH_WIDTH: LazyLock<usize> = LazyLock::new(|| {\\r\\n    // Some locales use a three-character wide month name (Jan to Dec);\\r\\n    // others vary between three to four (1月 to 12月, juil.). We check each month width\\r\\n    // to detect the longest and set the output format accordingly.\\r\\n    (0..11)\\r\\n        .map(|i| UnicodeWidthStr::width(&*LOCALE.short_month_name(i)))\\r\\n        .max()\\r\\n        .unwrap()\\r\\n});\\r\\n\\r\\n#[cfg(test)]\\r\\nmod test {\\r\\n    use super::*;\\r\\n\\r\\n    #[test]\\r\\n    fn short_month_width_japanese() {\\r\\n        let max_month_width = 4;\\r\\n        let month = \\\"1\\\\u{2F49}\\\"; // 1月\\r\\n        let padding = short_month_padding(max_month_width, month);\\r\\n        let final_str = format!(\\\"{month:<padding$}\\\");\\r\\n        assert_eq!(max_month_width, UnicodeWidthStr::width(final_str.as_str()));\\r\\n    }\\r\\n\\r\\n    #[test]\\r\\n    fn short_month_width_hindi() {\\r\\n        let max_month_width = 4;\\r\\n        assert!([\\r\\n            \\\"\\\\u{091C}\\\\u{0928}\\\\u{0970}\\\",                         // जन॰\\r\\n            \\\"\\\\u{092B}\\\\u{093C}\\\\u{0930}\\\\u{0970}\\\",                 // फ़र॰\\r\\n            \\\"\\\\u{092E}\\\\u{093E}\\\\u{0930}\\\\u{094D}\\\\u{091A}\\\",         // मार्च\\r\\n            \\\"\\\\u{0905}\\\\u{092A}\\\\u{094D}\\\\u{0930}\\\\u{0948}\\\\u{0932}\\\", // अप्रैल\\r\\n            \\\"\\\\u{092E}\\\\u{0908}\\\",                                 // मई\\r\\n            \\\"\\\\u{091C}\\\\u{0942}\\\\u{0928}\\\",                         // जून\\r\\n            \\\"\\\\u{091C}\\\\u{0941}\\\\u{0932}\\\\u{0970}\\\",                 // जुल॰\\r\\n            \\\"\\\\u{0905}\\\\u{0917}\\\\u{0970}\\\",                         // अग॰\\r\\n            \\\"\\\\u{0938}\\\\u{093F}\\\\u{0924}\\\\u{0970}\\\",                 // सित॰\\r\\n            \\\"\\\\u{0905}\\\\u{0915}\\\\u{094D}\\\\u{0924}\\\\u{0942}\\\\u{0970}\\\", // अक्तू॰\\r\\n            \\\"\\\\u{0928}\\\\u{0935}\\\\u{0970}\\\",                         // नव॰\\r\\n            \\\"\\\\u{0926}\\\\u{093F}\\\\u{0938}\\\\u{0970}\\\",                 // दिस॰\\r\\n        ]\\r\\n        .iter()\\r\\n        .map(|month| format!(\\r\\n            \\\"{:<width$}\\\",\\r\\n            month,\\r\\n            width = short_month_padding(max_month_width, month)\\r\\n        ))\\r\\n        .all(|string| UnicodeWidthStr::width(string.as_str()) == max_month_width));\\r\\n    }\\r\\n}\\r\\n\"}","command":"shell_command","command_index":7,"command_line":"{\"command\":\"$p='rust-reference/src/output/time.rs'; $c=Get-Content $p; $c[0..360]\",\"workdir\":\"C:\\\\Users\\\\liuliu\\\\Documents\\\\tura-benchmark\\\\raw\\\\project-rebuild-source-port\\\\r-c7e67bc81e\\\\eza\\\\tura-balanced-1\\\\workspace\"}","command_type":"shell_command","id":"runtime-18c0fdca2eee43d0.tool.command_run:call_eZedCty4jsrMIOUJI7KSX9zs:7","provider_tool_call_id":"call_eZedCty4jsrMIOUJI7KSX9zs","status":"completed","step":1,"type":"command_execution"},"type":"item.completed"}
