   recurse into directories as a tree","  -X, --dereference          dereference symbolic links when displaying information","  -F, --classify=WHEN        display type indicator by file names (always, auto, never)","  --colo[u]r=WHEN            when to use terminal colours (always, auto, never)","  --colo[u]r-scale           highlight levels of 'field' distinctly(all, age, size)","  --colo[u]r-scale-mode      use gradient or fixed colors in --color-scale (fixed, gradient)","  --icons=WHEN               when to display icons (always, auto, never)","  --no-quotes                don't quote file names with spaces","  --hyperlink                display entries as hyperlinks","  --absolute                 display entries with their absolute path (on, follow, off)","  --follow-symlinks          drill down into symbolic links that point to directories","  -w, --width COLS           set screen width in columns","","","FILTERING AND SORTING OPTIONS","  -a, --all                  show hidden and 'dot' files. Use this twice to also","                             show the '.' and '..' directories","  -A, --almost-all           equivalent to --all; included for compatibility with `ls -A`","  -d, --treat-dirs-as-files  list directories as files; don't list their contents","  -D, --only-dirs            list only directories","  -f, --only-files           list only files","  --show-symlinks            explicitly show symbolic links (for use with --only-dirs | --only-files)","  --no-symlinks              do not show symbolic links","  -L, --level DEPTH          limit the depth of recursion","  -r, --reverse              reverse the sort order","  -s, --sort SORT_FIELD      which field to sort by","  --group-directories-first  list directories before other files","  --group-directories-last   list directories after other files","  -I, --ignore-glob GLOBS    glob patterns (pipe-separated) of files to ignore","  --git-ignore               ignore files mentioned in '.gitignore'","  Valid sort fields:         name, Name, extension, Extension, size, type,","                             created, modified, accessed, changed, inode, and none.","                             date, time, old, and new all refer to modified.","","LONG VIEW OPTIONS","  -b, --binary               list file sizes with binary prefixes","  -B, --bytes                list file sizes in bytes, without any prefixes","  -g, --group                list each file's group","  --smart-group              only show group if it has a different name from owner","  -h, --header               add a header row to each column","  -H, --links                list each file's number of hard links","  -i, --inode                list each file's inode number","  -M, --mounts               show mount details (Linux and Mac only)","  -n, --numeric              list numeric user and group IDs","  -O, --flags                list file flags (Mac, BSD, and Windows only)","  -S, --blocksize            show size of allocated file system blocks","  -t, --time FIELD           which timestamp field to list (modified, accessed, created)","  -m, --modified             use the modified timestamp field","  -u, --accessed             use the accessed timestamp field","  -U, --created              use the created timestamp field","  --changed                  use the changed timestamp field","  --time-style               how to format timestamps (default, iso, long-iso,","                             full-iso, relative, or a custom style '+<FORMAT>'","                             like '+%Y-%m-%d %H:%M'","  --total-size               show the size of a directory as the size of all","                             files and directories inside (unix only)","  -o, --octal-permissions    list each file's permission in octal format","  --no-permissions           suppress the permissions field","  --no-filesize              suppress the filesize field","  --no-user                  suppress the user field","  --no-time                  suppress the time field","  --stdin                    read file names from stdin, one per line or other separator ","                             specified in environment","  --git                      list each file's Git status, if tracked or ignored","  --no-git                   suppress Git status (always overrides --git,","                             --git-repos, --git-repos-no-status)","  --git-repos                list root of git-tree status","  --git-repos-no-status      list each git-repos branch name (much faster)","    ","\"\"\"","","","FORBIDDEN = \"forbidden\"","NECESSARY = \"necessary\"","OPTIONAL = \"optional\"","WHEN = (\"always\", \"auto\", \"never\")","","","@dataclass(frozen=True)","class Spec:","    long: str","    short: str | None = None","    takes: str = FORBIDDEN","    choices: tuple[str, ...] | None = None","    default: str | None = None","","","SPECS = [","    Spec(\"version\", \"v\"), Spec(\"help\", \"?\"),","    Spec(\"oneline\", \"1\"), Spec(\"long\", \"l\"), Spec(\"grid\", \"G\"),","    Spec(\"across\", \"x\"), Spec(\"recurse\", \"R\"), Spec(\"tree\", \"T\"),","    Spec(\"classify\", \"F\", OPTIONAL, WHEN, \"auto\"), Spec(\"dereference\", \"X\"),","    Spec(\"width\", \"w\", NECESSARY), Spec(\"no-quotes\"),","    Spec(\"absolute\", None, OPTIONAL, (\"on\", \"follow\", \"off\"), \"on\"),","    Spec(\"follow-symlinks\"), Spec(\"color\", None, OPTIONAL, WHEN, \"auto\"),","    Spec(\"colour\", None, OPTIONAL, WHEN, \"auto\"),","    Spec(\"color-scale\", None, OPTIONAL, (\"all\", \"size\", \"age\"), \"all\"),","    Spec(\"colour-scale\", None, OPTIONAL, (\"all\", \"size\", \"age\"), \"all\"),","    Spec(\"color-scale-mode\", None, NECESSARY, (\"fixed\", \"gradient\")),","    Spec(\"colour-scale-mode\", None, NECESSARY, (\"fixed\", \"gradient\")),","    Spec(\"all\", \"a\"), Spec(\"almost-all\", \"A\"),","    Spec(\"treat-dirs-as-files\", \"d\"), Spec(\"list-dirs\"),","    Spec(\"level\", \"L\", NECESSARY), Spec(\"reverse\", \"r\"),","    Spec(\"sort\", \"s\", NECESSARY, (","        \"name\", \"Name\", \"size\", \"extension\", \"Extension\", \"modified\",","        \"changed\", \"accessed\", \"created\", \"inode\", \"type\", \"none\",","    )),","    Spec(\"ignore-glob\", \"I\", NECESSARY), Spec(\"git-ignore\"),","    Spec(\"group-directories-first\"), Spec(\"group-directories-last\"),","    Spec(\"only-dirs\", \"D\"), Spec(\"only-files\", \"f\"), Spec(\"no-symlinks\"),","    Spec(\"show-symlinks\"), Spec(\"binary\", \"b\"), Spec(\"bytes\", \"B\"),","    Spec(\"group\", \"g\"), Spec(\"numeric\", \"n\"), Spec(\"header\", \"h\"),","    Spec(\"icons\", None, OPTIONAL, WHEN, \"auto\"), Spec(\"inode\", \"i\"),","    Spec(\"links\", \"H\"), Spec(\"modified\", \"m\"), Spec(\"changed\"),","    Spec(\"blocksize\", \"S\"), Spec(\"total-size\"),","    Spec(\"time\", \"t\", NECESSARY, (\"modified\", \"changed\", \"accessed\", \"created\")),","    Spec(\"accessed\", \"u\"), Spec(\"created\", \"U\"),","    Spec(\"time-style\", None, NECESSARY, (\"default\", \"long-iso\", \"full-iso\", \"iso\", \"relative\")),","    Spec(\"hyperlink\"), Spec(\"mounts\", \"M\"), Spec(\"smart-group\"),","    Spec(\"no-permissions\"), Spec(\"no-filesize\"), Spec(\"no-user\"), Spec(\"no-time\"),","    Spec(\"git\"), Spec(\"no-git\"), Spec(\"git-repos\"), Spec(\"git-repos-no-status\"),","    Spec(\"extended\", \"@\"), Spec(\"octal-permissions\", \"o\"), Spec(\"context\", \"Z\"),","    Spec(\"stdin\"), Spec(\"flags\", \"O\"),","]","BY_LONG = {spec.long: spec for spec in SPECS}","BY_SHORT = {spec.short: spec for spec in SPECS if spec.short is not None}","","","class OptionError(Exception):","    pass","","","@dataclass","class Flag:","    name: str","    value: str | None","    spelling: str","    order: int","","","@dataclass","class Options:","    flags: list[Flag] = field(default_factory=list)","    paths: list[str] = field(default_factory=list)","","    def has(self, name: str) -> bool:","        return any(flag.name == name for flag in self.flags)","","    def count(self, name: str) -> int:","        return sum(flag.name == name for flag in self.flags)","","    def get(self, name: str) -> str | None:","        for flag in reversed(self.flags):","            if flag.name == name:","                return flag.value","        return None","","    def last_of(self, names: set[str]) -> Flag | None:","        return next((f for f in reversed(self.flags) if f.name in names), None)","","","def choices_text(values: Sequence[str]) -> str:","    return \"choices: \" + \", \".join(values)","","","def needs_value(flag: str, spec: Spec) -> OptionError:","    suffix = f\" ({choices_text(spec.choices)})\" if spec.choices else \"\"","    return OptionError(f\"Flag {flag} needs a value{suffix}\")","","","def parse_args(argv: Sequence[str]) -> Options:","    result = Options()","    parsing = True","    index = 0","    order = 0","    while index < len(argv):","        token = argv[index]","        index += 1","        if not parsing:","            result.paths.append(token)","            continue","        if token == \"--\":","            parsing = False","            continue","        if token.startswith(\"--\"):","            raw = token[2:]","            name, equal, attached = raw.partition(\"=\")","            spec = BY_LONG.get(name)","            if spec is None:","                raise OptionError(f\"Unknown argument --{name}\")","            spelling = f\"--{name}\"","            value: str | None = None","            if equal:","                if spec.takes == FORBIDDEN:","                    raise OptionError(f\"Flag {spelling} cannot take a value\")","                value = attached","            elif spec.takes == NECESSARY:","                if index >= len(argv):","                    raise needs_value(spelling, spec)","                value = argv[index]","                index += 1","            elif spec.takes == OPTIONAL:","                if index < len(argv) and spec.choices and argv[index] in spec.choices:","                    value = argv[index]","                    index += 1","                else:","                    value = spec.default","            result.flags.append(Flag(name, value, spelling, order))","            order += 1","            continue","        if token.startswith(\"-\") and token != \"-\":","            cluster = token[1:]","            before_equal, equal, attached = cluster.partition(\"=\")","            pos = 0","            while pos < len(before_equal):","                short = before_equal[pos]","                spec = BY_SHORT.get(short)","                if spec is None:","                    raise OptionError(f\"Unknown argument -{short}\")","                spelling = f\"-{short}\"","                value = None","                remainder = before_equal[pos + 1:]","                is_value_flag = pos == len(before_equal) - 1 and bool(equal)","                if is_value_flag:","                    if spec.takes == FORBIDDEN:","                        raise OptionError(f\"Flag {spelling} cannot take a value\")","                    value = attached","                    pos = len(before_equal)","                elif spec.takes == NECESSARY:","                    if remainder:","                        value = remainder","                    elif index < len(argv):","                        value = argv[index]","                        index += 1","                    else:","                        raise needs_value(spelling, spec)","                    pos = len(before_equal)","                elif spec.takes == OPTIONAL:","                    if remainder:","                        if spec.choices and remainder not in spec.choices:","                            raise OptionError(f\"Flag {spelling} cannot take a value\")","                        value = remainder","                        pos = len(before_equal)","                    elif index < len(argv) and spec.choices and argv[index] in spec.choices:","                        value = argv[index]","                        index += 1","                        pos += 1","                    else:","                        value = spec.default","                        pos += 1","                else:","                    pos += 1","                result.flags.append(Flag(spec.long, value, spelling, order))","                order += 1","            continue","        result.paths.append(token)","    return result","","","def rust_debug(value: str) -> str:","    return json.dumps(value, ensure_ascii=False)","","","def option_arg_name(name: str) -> str:","    spec = BY_LONG[name]","    return f\"--{name}\" + (f\" (-{spec.short})\" if spec.short else \"\")","","","def validate_options(options: Options) -> None:","    validators = {","        \"color\": WHEN, \"colour\": WHEN, \"icons\": WHEN,","        \"classify\": (\"always\", \"auto\", \"automatic\", \"never\"),","        \"absolute\": (\"on\", \"yes\", \"follow\", \"off\", \"no\"),","        \"color-scale-mode\": (\"fixed\", \"gradient\"),","        \"colour-scale-mode\": (\"fixed\", \"gradient\"),","    }","    for name, values in validators.items():","        value = options.get(name)","        if value is not None and value not in values:","            raise OptionError(f\"Option {option_arg_name(name)} has no {rust_debug(value)} setting\")","","    sort_value = options.get(\"sort\")","    sort_aliases = {","        \"name\", \"filename\", \"Name\", \"Filename\", \".name\", \".filename\", \".Name\",","        \".Filename\", \"size\", \"filesize\", \"ext\", \"extension\", \"Ext\", \"Extension\",","        \"date\", \"time\", \"mod\", \"modified\", \"new\", \"newest\", \"age\", \"old\", \"oldest\",","        \"ch\", \"changed\", \"acc\", \"accessed\", \"cr\", \"created\", \"inode\", \"type\", \"none\",","    }","    if sort_value is not None and sort_value not in sort_aliases:","        values = BY_LONG[\"sort\"].choices or ()","        raise OptionError(","            f\"Option {option_arg_name('sort')} has no {rust_debug(sort_value)} setting \"","            f\"({choices_text(values)})\"","        )","","    for numeric in (\"level\", \"width\"):","        value = options.get(numeric)","        if value is not None:","            try:","                parsed = int(value)","                if parsed < 0:","                    raise ValueError","            except ValueError as error:","                message = \"invalid digit found in string\" if value else \"cannot parse integer from empty string\"","                raise OptionError(","                    f\"Value {rust_debug(value)} not valid for option {option_arg_name(numeric)}: {message}\"","                ) from error","    if options.has(\"tree\") and options.count(\"all\") >= 2:","        raise OptionError(\"Option --tree is useless given --all --all\")","","","@dataclass","class View:","    mode: str","    tree: bool","    long: bool","    recurse: bool","    as_file: bool","    max_depth: int | None","","","def deduce_view(options: Options) -> View:","    selector = options.last_of({\"long\", \"oneline\", \"grid\", \"tree\"})","    has_long = options.has(\"long\")","    mode = \"lines\"","    if selector is None:","        mode = \"grid\" if sys.stdout.isatty() else \"lines\"","    elif selector.name == \"long\" or (","        selector.name in {\"tree\", \"grid\"} and has_long","    ):","        later = options.last_of({\"grid\", \"tree\"})","        mode = \"grid-long\" if later and later.name == \"grid\" else \"details\"","    elif selector.name == \"tree\":","        mode = \"details\"","    elif selector.name == \"grid\":","        mode = \"grid\"","    else:","        mode = \"lines\"","","    can_tree = mode == \"details\"","    tree = options.has(\"tree\") and can_tree","    recurse = tree or options.has(\"recurse\")","    as_file = options.has(\"treat-dirs-as-files\") or options.has(\"list-dirs\") or tree","    max_depth = int(options